public protocol Actor : AnyObject, Sendable {
    nonisolated var unownedExecutor: UnownedSerialExecutor { get }
}

@frozen public struct AnyPublisher<Output, Failure> : CustomStringConvertible, Publisher where Failure : Error {
    public init<P>(_ publisher: P) where Output == P.Output, Failure == P.Failure, P : Publisher
}

@MainActor public protocol App {
    associatedtype Body : Scene
    @SceneBuilder @MainActor var body: Self.Body { get }
}

codeSample:
@main
struct MyApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}

