public protocol AppIntent : DisplayRepresentationProviding, PersistentlyIdentifiable {
    static var title: LocalizedStringResource { get }
    func perform() async throws -> some IntentResult
}

public struct AppShortcut {
    public init(intent: some AppIntent, phrases: [AppShortcutPhrase<some AppIntent>], shortTitle: LocalizedStringResource, systemImageName: String)
}

